import copy
import ipaddress
from collections.abc import Mapping
from dataclasses import dataclass


@dataclass(frozen=True)
class NodeRecord:
    hostname: str
    address: str
    purpose: object
    platform: str
    cpu_count: object
    memory: object
    active: bool
    metadata: dict


def create_node(hostname, address, purpose=None, platform="linux", cpu_count=None,
                memory=None, active=True, metadata=None):
    if not isinstance(hostname, str) or not 1 <= len(hostname.strip()) <= 48:
        raise ValueError("invalid hostname")
    if not isinstance(address, str):
        raise ValueError("invalid address")
    try:
        canonical_address = str(ipaddress.ip_address(address))
    except ValueError:
        raise ValueError("invalid address") from None
    if purpose is not None and (not isinstance(purpose, str) or len(purpose) > 80):
        raise ValueError("invalid purpose")
    if platform not in {"linux", "bsd", "other"}:
        raise ValueError("invalid platform")
    if cpu_count is not None and (not isinstance(cpu_count, int) or cpu_count <= 0):
        raise ValueError("invalid cpu_count")
    if memory is not None and (not isinstance(memory, str) or len(memory) > 24):
        raise ValueError("invalid memory")
    if not isinstance(active, bool):
        raise ValueError("invalid active flag")
    if metadata is None:
        metadata = {}
    if not isinstance(metadata, Mapping):
        raise ValueError("invalid metadata")
    return NodeRecord(hostname.strip(), canonical_address, purpose, platform,
                      cpu_count, memory, active, copy.deepcopy(dict(metadata)))

